/** A database level of the Steam Knight, his pinned native tree, the templates, the projectile and the clips. */
export function steamKnightNative(r,n){
 const lv=LEVELS[r?.level];
 if(!isSteamKnight(r)||!lv||r.key!==r.prefabKey||r.notCountInTotal||r.applyWay!=="MELEE"||Object.entries(lv.stats).some(([k,v])=>!same(r.stats[k],v))
  ||!same(r.abilities,ABILITIES)||!same(r.talents,lv.talents)||!same(r.skills,lv.skills)||!same(r.sp,SP))return false;
 if(!same(closure(n),SPEC)||Object.entries(TEMPLATES).some(([k,v])=>!same(n.$template(k),v))
  ||Object.entries(PROJECTILES).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v)))return false;
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=clocks.enemies[r.prefabKey];
 return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
  &&Object.entries(CLOCK.durations).every(([k,v])=>same(clock.durations[k],v))
  &&Object.entries(CLOCK.events).every(([k,v])=>same(clock.events[k]?.filter(x=>x.name==="OnAttack").map(x=>x.time),v));
}
// The sparse overlay: level zero's talents and skills with this level's own values by key / prefab key.
function overlayTalents(r){
 const L0=LEVELS[0].talents,bb={...L0.bb,...r.talents.bb},bbStr={...L0.bbStr,...r.talents.bbStr},groups={};
 for(const k of Object.keys({...bb,...bbStr})){const i=k.indexOf("."),g=i>0?k.slice(0,i):k;(groups[g]??=[]).push(i>0?k.slice(i+1):"");}
 for(const g of Object.values(groups))g.sort();
 return {bb,bbStr,groups};
}
const overlaySkills=r=>LEVELS[0].skills.map(s=>r.skills.find(x=>x.prefabKey===s.prefabKey)??s);
const anim=k=>({dur:CLOCK.durations[k],hit:CLOCK.events[k]?.[0]??0});
const hard=v=>{if(v==="true")return true;if(v==="false")return false;throw Error("Invalid Steam Knight is_hard_level");};
export function steamKnightParams(r){
 const {bb:t,bbStr:ts}=overlayTalents(r),skills=overlaySkills(r),sk=k=>skills.find(s=>s.prefabKey===k);
 const boost=sk("Boost"),zan=sk("Zantetsuken"),hb1=sk("HeroBomb[first_state]"),hb2=sk("HeroBomb[second_state]");
 return {
  attack:{scale:1,anim:[anim("Attack_A"),anim("Attack_B")]},
  sp:{max:SP.maxSp,initial:SP.initSp,increment:SP.increment},
  debut:{aspd:t["BornWeak.attack_speed"],move:t["BornWeak.move_speed"]},
  boost:{cooldown:boost.cooldown,initial:boost.initCooldown,duration:boost.bb.boost_duration,aspd:boost.bb.attack_speed,move:boost.bb.move_speed,
   resistance:boost.bb.damage_resistance,stun:boost.bb.stun,hard:hard(boost.bbStr.is_hard_level),anim:{dur:CLOCK.durations.Boost_A,hit:0}},
  zantetsuken:{cost:zan.spCost,times:zan.bb.times,scale:zan.bb.atk_scale,duration:zan.bb.duration,strike:[anim("Skill_1_Attack_A"),anim("Skill_1_Attack_B")]},
  bomb:{first:{threshold:t["TriggerHeroBomb.hp_ratio"],targets:1,scale:hb1.bb.atk_scale,mark:hb1.bb.mark_duration,hard:hard(hb1.bbStr.is_hard_level)},
   second:{threshold:t["TriggerHeroBomb_2.hp_ratio"],targets:2,scale:hb2.bb.atk_scale,mark:hb2.bb.mark_duration,hard:hard(hb2.bbStr.is_hard_level)},
   fly:[CLOCK.durations.Skill_2_Begin_A,CLOCK.durations.Skill_2_Begin_B],land:[CLOCK.durations.Skill_2_End_A,CLOCK.durations.Skill_2_End_B],
   life:5.5,interval:.5,maxHits:8,delay:.2,tiles:[-1,0,1].flatMap(dr=>[-1,0,1].map(dc=>[dr,dc]))},
  revive:{duration:t["reborn.duration"],invincible:t["reborn.stmkgt_t_state_2[reborn_invincible].duration"],aspd:t["reborn.attack_speed"],
   move:t["reborn.move_speed"],def:t["reborn.def"],res:t["reborn.magic_resistance"],resistance:t["reborn.damage_resistance"],
   hard:hard(ts["reborn.is_hard_level"]),bombDelay:.1},
 };
}
const TEXTS=ABILITIES.map(a=>a.text);
const feature={matchesRecord:isSteamKnight,covers:steamKnightNative};
const hardLevel=v=>v==="true"||v==="false";
const HERO_BOMBS=["HeroBomb[first_state]","HeroBomb[second_state]"];
export const STEAM_KNIGHT_FEATURES={
 // Both levels carry skill:Boost, so it holds the runtime, the native claims and the stage parameters.
 "skill:Boost":{...feature,ability:{kind:"steamKnight",params:steamKnightParams},explains:text=>TEXTS.includes(text),
  nativeClaim:()=>({wrappers:4}),
  note:"Debut slow, Boost (stun or damage resistance), Zantetsuken, HeroBomb bombardment, the revive into the boosted second form",
  stageSparseTalents:r=>r.level===1?overlayTalents(r):null,
  stageSparseSkills:r=>overlaySkills(r),
  // A stage list naming some of his skills changes those in place and keeps the others.
  stageSkillSetOverride:(r,keys)=>keys.every(k=>LEVELS[0].skills.some(s=>s.prefabKey===k)),
  // H11-4 adverse: second-form movement +0.5. Values only; the meaning of the key is reviewed.
  stageOverrides:{"reborn.move_speed":v=>Number.isFinite(v)&&v>=0&&v<=2},
  stageStringOverrides:{"reborn.is_hard_level":hardLevel},
  // HeroBomb is cast only through TriggerEnemySkill, which ignores its cooldown (HeroBomb[second_state] has 99999/99999
  // in the database and still runs on every revive), so the stages' 0 / 99999 initial cooldowns change nothing.
  stageSkillTimingOverrides:{"Boost":{initCooldown:v=>Number.isFinite(v)&&v>=0&&v<=600},
   ...Object.fromEntries(HERO_BOMBS.map(k=>[k,{initCooldown:v=>v===0||v===99999}]))},
  stageSkillStringOverrides:{"Boost":{is_hard_level:hardLevel},...Object.fromEntries(HERO_BOMBS.map(k=>[k,{is_hard_level:hardLevel}]))}},
 "talent:BornWeak":{...feature,note:"the debut slow (skill:Boost)"},
 "talent:TriggerHeroBomb":{...feature,note:"first-form HeroBomb trigger (skill:Boost)"},
 "talent:TriggerHeroBomb_2":{...feature,note:"second-form HeroBomb trigger (skill:Boost)"},
 "skill:Zantetsuken":{...feature,note:"run by skill:Boost"},
 "skill:HeroBomb[first_state]":{...feature,note:"run by skill:Boost"},"skill:HeroBomb[second_state]":{...feature,note:"run by skill:Boost"},
};
